from collections import deque


def shortestWalkAllNodes(graph):
    n = len(graph)
    full = (1 << n) - 1
    if n == 1:
        return 0
    seen = [[False] * n for _ in range(1 << n)]
    dq = deque()
    for i in range(n):
        seen[1 << i][i] = True
        dq.append((1 << i, i, 0))
    while dq:
        mask, u, d = dq.popleft()
        for v in graph[u]:
            nm = mask | (1 << v)
            if nm == full:
                return d + 1
            if not seen[nm][v]:
                seen[nm][v] = True
                dq.append((nm, v, d + 1))
    return -1
